def bench(fn, name, budget_ms=700):
    fn(STATES[0])
    n = 0
    t0 = watch.time()
    while watch.time() - t0 < budget_ms:
        for s in STATES:
            fn(s); fn(s); fn(s)
        n += 9
    dt = watch.time() - t0
    print(name, ":", dt * 1000 // n, "us/call")

